请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-003

=== 用户原始指令 (query.txt) ===
整个余额显示的卡呢,带数字一行字,点跳应用,看天气,提醒我快没钱了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个余额显示的卡呢,带数字一行字,点跳应用,看天气,提醒我快没钱了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "summary": {
      "balanceText": {
        "type": "string",
        "description": "余额主数字展示文本，使用脱敏样例金额。",
        "sampleValue": "¥28.60"
      },
      "reminderText": {
        "type": "string",
        "description": "余额不足的短提醒文案。",
        "sampleValue": "提醒：快没钱了"
      },
      "statusText": {
        "type": "string",
        "description": "余额状态短标签。",
        "sampleValue": "低余额"
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称。",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/partly_cloudy.png",
      "description": "云朵在前、太阳在后的彩色天气图标，适合表达多云或天气入口。"
    }
  ]
}

